const fs = require('fs');
const path = require('path');
const assert = require('assert');
const { JSDOM } = require('jsdom');

const initialGlobals = new Set(Object.getOwnPropertyNames(global));

// Load app files into 3 successive JSDOM instances
for (let iteration = 1; iteration <= 3; iteration++) {
  const dom = new JSDOM(fs.readFileSync('app/index.html', 'utf8'), {
    url: 'http://localhost/#home',
    runScripts: 'outside-only'
  });
  const win = dom.window;

  // Eval core app files
  const files = [
    'app/js/config.js',
    'app/js/navigation.js',
    'app/js/tmdb.js',
    'app/js/views/home.js',
    'app/js/views/catalog.js',
    'app/js/views/search.js',
    'app/js/views/details.js',
    'app/js/app.js'
  ];
  for (const f of files) {
    win.eval(fs.readFileSync(f, 'utf8'));
  }

  // Init app
  win.CinejoyApp.init();

  // Verify app exists on window
  assert(win.CinejoyApp, 'CinejoyApp exists on window');
  assert(win.SpatialNav, 'SpatialNav exists on window');

  // Verify app DOES NOT exist on Node global
  assert.strictEqual(typeof global.CinejoyApp, 'undefined', 'CinejoyApp must not pollute global');
  assert.strictEqual(typeof global.SpatialNav, 'undefined', 'SpatialNav must not pollute global');
  assert.strictEqual(typeof global.TmdbClient, 'undefined', 'TmdbClient must not pollute global');
  assert.strictEqual(typeof global.window, 'undefined', 'window must not pollute global');
  assert.strictEqual(typeof global.document, 'undefined', 'document must not pollute global');
}

const finalGlobals = new Set(Object.getOwnPropertyNames(global));
const leaked = [...finalGlobals].filter(k => !initialGlobals.has(k));

console.log('New globals leaked into Node.js process:', leaked);
assert.strictEqual(leaked.length, 0, 'No globals should be leaked');
console.log('TEST PASS: Zero global pollution detected across JSDOM transitions.');
"

